insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('35c606c6-e002-5566-a53e-921c39c1a1f4','Mike Colt','mcolt88@icloud.com','Krivak9team@gmail.com','mcolt@dogwiseacademy.com','(518) 821-2109','503 NJ-94 , Columbia, NJ 07832','Columbia','NJ','07832',40.9388,-75.055,'Driving range: 4 hours',200,8,24,'All programs','All programs','Can go to CT','Jahrony','L shirt / 2XL hoodie',null,null,null,'Sara Kostadinovska wife 329-202-7111',null,'I grew up immersed in the dog world, attending dog shows and field trials as a youth. At 14, I shifted my focus to field trials and later assisted my uncle in training dogs from his AKC-historic kennel, ''Chickasaw Goldens,'' helping them achieve Master Hunter titles and pass Senior Hunt Tests. In my early 20s, I developed a passion for training Military Working Dogs, patrol dogs, and personal protection dogs. I am a certified decoy for the APPDA and, in my free time, I enjoy training personal protection dogs and competing.',true,'{}'::text[]) on conflict (id) do nothing;
