insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('f4b85e5a-0c89-5268-b05a-99cdd0149020','Drew Thompson','dogmandrew0921@gmail.com',null,'athompson@dogwiseacademy.com','(203) 722-4469','85 Northfield St , Bridgeport CT 06606','Bridgeport','CT','06606',41.2091,-73.2086,'Driving Range: 2 hours / 100 miles',100,2,6,'All programs','All programs',null,'Anita','L',null,'Blue Cross Animal Hospital','VCA Norwalk CT','2035431782  Girlfriend','2024-11-01','My name is Andrew I''m a expert dog trainer with a deep passion for dogs. I have been dedicated to honing my skills since 2019, when I was introduced to the NePoPo® philosophy by Certified Dog Trainer & NePoPo® Gold Graduate. Since then I have pursued extensive knowledge in dog training through attending numerous seminars, webinars, and schools conducted by highly regarded trainers. I recently earned the title of New NePoPo® Gold Graduate under the guidance of Kirubell Yohannes, which signifies mastery of the Modern Art of Dog Training. My journey as a dog trainer began with a genuine love and enthusiasm for dogs.',true,'{}'::text[]) on conflict (id) do nothing;
