insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('b627150f-b2ec-51d1-be2a-dd1201c7410f','April Crawford','ehcharmaine@gmail.com','crawford.k9nnels@gmail.com','acrawford@dogwiseacademy.com','(757) 230-9042','1369 Auburn Hill Drive Chesapeake VA 23320','Chesapeake','VA','23320',36.7352,-76.2384,'Driving range: 2 hours',100,3,9,'All programs','All programs','She is willing to work North Carolina & Virginia Beach, VA and the surrounding 7 cities all the way to Washington DC','Anita','L',null,'Disputanta Animal Hospital 8401 County Dr Disputanta, VA 23842','Disputanta Animal hospital 8401 County Dr Disputanta, VA 23842','Terry Crawford- Mother 7575150614','2025-04-11','Hi there! My name is April- Charmaine, I have been working dogs since 2015. Boarding, animal husbandry, breeding, handling of local law enforcement K9s, Narcotics Detection K9 training and handling and pet dog OB training with an emphasis on rehabilitation programs. I am familiar with and train dogs of all breeds, ages and temperaments. The well-being of your dog is of the utmost importance to me. I strive to be the olive branch between you and your precious companion and together, find the perfect communication tool set. Finding their success and yours using specifically tailored training methods is what I desire to achieve while your pet is under my care. Living a well balanced harmonious life with your dog is one of life''s many pleasures and I plan to get you there!
