insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('59e998eb-3886-5b60-b935-ecbf71c2548d','Tressie Courtney','ttbcourtney@gmail.com',null,'tcourtney@dogwiseacademy.com','(209) 304-7136','83 Myers lane, St. Matthews SC','Ronkonkoma','NY','11779',40.8083,-73.1305,'Driving range: 2.5 hours',125,8,24,'All programs','All programs','Confirm if client needs specific pickup/dropoff date due to Tressie''s busy schedule','Anita','S',null,'NA','NA','David Santiago- 803-422-3171','2025-07-22','Tressie started training dogs right after she graduated from high school which was 16 years ago. What started as a side job to pay for college, is now her career. She has certifications for AKC CGC, pet food nutrition specialist, raw dog food nutrition, advanced canine nutrition, canine essential oils and advanced canine homeopathy. She also competes in the dog sport PSA (protection sport association) where she is a national competitor and training director for a local dog club. She has experience with raising puppies, behavior modification, competition obedience, protection training and basic-advanced training.',true,array['Location conflict: sheet says SC, your list says Ronkonkoma, NY']::text[]) on conflict (id) do nothing;
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('d8982535-ee6d-5191-846d-ef5303952a6f','Jason Lewis','j.alexander.lewis81@gmail.com',null,'jlewis@dogwiseacademy.com','(813) 724-9960','3076 Old Windmill Road, Ridgeway, SC 29130','Ridgeway','SC','29130',34.3167,-80.9288,'Driving range: 250 miles (Atlanta, GA)',250,4,12,'All Programs','All Programs',null,'Jahrony','M',null,null,null,'Kenneth Lewis 4047714235',null,'Meet Jason, a lifelong dog lover and experienced dog trainer with 19 years of professional experience. Jason has been working with dogs since the age of 3 and has always had a passion for training and caring for animals. This passion led Jason to start working with animals at an exotic pet store at the age of 13, and eventually, to pursue a career in dog training.
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('0598bd9d-b735-5add-b551-6b4ea35afd4a','Theresa Strickland','K9traineratl@gmail.com',null,'tstrickland@dogwiseacademy.com','(770) 231-8356','370 Jade Cove Dr, Roswell, GA 30075','Roswell','GA','30075',34.0408,-84.3859,'Driving range: 40 miles',40,6,18,'2,3,4 week programs. Rehabs need to be asked first','Basic, Advanced, Anxiety, Agression *ask first',null,'Anita','S',null,'Orr animal hospital is mine. Blue pearl is local er vet','Blue pearl sandy springs ga','Seth Blakeman (finance) 404-398-7504','2025-02-04','Hi my names Theresa I’ve been training dogs 10+ years! Born and raised in north Georgia I got my first dog when I was 7 and fell in love with training dogs and animals! Today I own 2 belgian malinois named Echo and Holly who both have the CGC (canine hood citizen) and working towards Titles! I am currently CPR & Heat stroke certificated along with my CPDT-KA Certification along with AKC evaluator Certified! Training dogs is my life time passion!! I have experienced all the way from Puppy training all the way up to protection training, willing to help in any area I can!',true,'{}'::text[]) on conflict (id) do nothing;
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('d9455803-dc19-5d8c-b6db-49bf0746c608','Opal O''Brien','opawz@opawzdogtraining.com',null,'oobrien@dogwiseacademy.com','(404) 368-1465','5769 Little Oak Trail SW, Stone Mountain, GA 30087','Stone Mountain','GA','30087',33.8082,-84.1702,'Driving range: 1.5 hours',75,2,6,'All programs','All programs',null,'Anita','2XL',null,'Beaver Crossing Animal Hospital 4184 Lawrenceville Hwy, Lilburn, GA 30047','BluePearl Pet Hospital 1956 Lawrenceville-Suwanee Rd  Lawrenceville, GA 30043','Robert O’Brien 404-368-1135 (Husband) Eunice Thomas 914-649-9758 (Mother)','2025-05-03','Opal O’Brien, owner & dog trainer with OPAWZ DOG TRAINING LLC. Opal was born in Kingston, Jamaica, West Indies.  She currently lives in Stone Mountain, GA
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('9c5bb53f-1824-5d96-91b7-b452ebde5b5f','Jarret Price','pricelessk9.3@gmail.com',null,'jprice@dogwiseacademy.com','(609) 500-3137','101 Blue Meadow Dr, Kathleen, GA 31047','Kathleen','GA','31047',32.4672,-83.6128,'Driving range: 50-60 miles',60,2,6,'All programs','All programs',null,'Anita','L',null,'Mount laurel Animal hospital  220 mount lourel rd. Mt. Laurel twp.  NJ 08054','Mount laurel Animal hospital  220 mount lourel rd. Mt. Laurel twp.  NJ 08054','Marsha Burton  718-809-5592','2024-07-26','My name is Jarret Price, I''m 34 years old, single parent of a 14 year old son. I''ve been a professional dog trainers for 3 years now. I''ve always had a love for animals at a young age, I fell in love with dogs when I would watch my grandfather train with his duck dogs. I was really intrigued on how well they would listen to his commands. When I first started my dog training journey,  I built out a school bus into a mobile home, I took an apprenticeship at Hercules adog Training Academy 2 hours away from my hometown.  I left and good paying job and followed my calling. I lived in my mentors back yard in the bus and learn the art of being a dog trainer. I''ve worked countless dogs running the facility. Dogs from basic obedience to the worst cases nobody else would take. I also learned how to be a decoy and work dogs in protection work and I also learned how to do schutzhund tracking. I love a good challenge and the most rewarding part is watching the owner enjoy their companion and understanding them alot better. I enjoy the science and training methods used on various dogs. I''m a fan of all the breeds and love to take on a new challenge.  Over the past year I have dove into training hunting dogs from bird dogs to dogs tracking down wounded deer. I''m looking forward to continuing my knowledge and learning each day.',true,'{}'::text[]) on conflict (id) do nothing;
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('17dc7c8c-00f0-5287-9855-466df9ba7645','Rina Sullivan','pawsnclawsfl@gmail.com',null,'rsullivan@dogwiseacademy.com','(571) 247-3394','5765 Outback Ave SW, Grant-Valkaria, FL 32909','Palm Bay','FL','32909',27.9694,-80.6473,'Driving Range: 1 hour - NO TAMPA',50,2,6,'All Programs','All Programs',null,'Anita','XL MEN',null,'Mcabees 4586 n palmetto Ave winter park Fl 32792','Oviedo ER  2092 church st Oviedo Fl 32765','Kevin Sullivan- husband 571-247-3393','2024-10-15','I am Rina Sullivan and have been training dogs for 27 years. I train obedience and specialize in rehabilitation whether there is anxiety or aggression. I have been a vet tech and majored in pre vet at the University of Maryland. I am experienced with medical and behavioral issues. I was also an animal control officer and tried to keep dogs adoptable in the shelter by rescuing and training them. Dogs are my life, I have studied behaviors and positive reinforcement over the years. I believe in a relationship where humans and their dogs live happily and respect each other. I believe that consistency and exercise is key to fulfilling a happy life for dogs.',true,'{}'::text[]) on conflict (id) do nothing;
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('ee8d0574-3e2a-506c-9207-e5f0f6d347b3','James Guillory','wjamesguillory@gmail.com',null,'jguillory@dogwiseacademy.com','(202) 297-2664','16312 Birkdale Dr, , Odessa FL 33556','Odessa','FL','33556',28.1421,-82.5905,'Driving range: 200 miles',200,4,12,'All programs','All programs',null,'Anita',null,null,null,null,'Tenique Jackson (gf) (202) 813-2007','2025-06-18','With over two decades of experience in competitive and pet dog training,  James Guillory is a respected leader in the world of canine behavior, law enforcement K9 preparation, and dog sport competition. 
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('fa93d0ea-5845-517d-afdb-da09282f3f32','Tracie Dulniak','Tshelbie3@gmail.com',null,'tdulniak@dogwiseacademy.com','(505) 480-1973','5611 Atlanta street Hollywood Florida 33021','Fort Lauderdale','FL','33315',26.0989,-80.1541,'Driving Range: 1 hour',50,2,6,'All Programs','All programs','Only 2 dogs at a time, and only 1 dog when booking a rehab','Anita','L',null,'North Federal animal hospital  1100 Federal Highway  Fort Lauderdale, FL 33316','South Federal Animal hospital 1230 South Andrews  Fort Lauderdale, FL 33316','Laura Westlake - Friend 7169094265','2025-03-06','Hi.  My name is Tracie Dulniak and I''ve been training dogs and humans for over 25 yrs and helping families understand the dynamics at the end of the leash. I have extensive training in the areas of Service Dogs, serious behavior issues, socialization, various tools and I train in both a positive and balanced ideology. I can help owners understand the WHY behind their dogs behavior and help them understand the reasons behind reactivity, aggressiveness, breed specific instinctual behavior and how to successfully and safely overcome those issues and how to socialize your dog.
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('44d14833-b0eb-58f3-bf80-6b1589c68d17','Melina Molinare','ladymeliners@gmail.com',null,'mmolinare@dogwiseacademy.com','(305) 216-5444','3438 SW 24th St, Miami, FL 33145','Miami','FL','33145',25.7539,-80.2253,'Driving range: 1.5 hours',75,2,6,'Starting with Basic programs - confirm for rehabs','Basic, Advanced, Anxiety *ask first, Agression *ask first',null,'Anita',null,null,null,null,'Rodney Madu - partner (305) 898-8902','2025-02-17','Hello, I''m Melina, and I''m thrilled to be a part of the team! My passion for animals has been a guiding force throughout my life. I''ve dedicated countless hours to volunteering with local rescues here in Miami, helping dogs find their forever homes. My commitment to animal welfare also led me to Mexico each summer, where I assisted with spay/neuter clinics, handling everything from pre-op to post-op care. I even worked to socialize feral cats to prepare them for adoption and fostered many cats in need.
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('26c67a64-5fdd-5f9f-a4be-ea9a2da23c27','Bailey Preston','b_preston37@yahoo.com','bprestonk9@gmail.com','bpreston@dogwiseacademy.com','(989) 400-3425','3179 Pontiac Lake Rd, Waterford Township, MI 48328','Waterford','MI','48328',42.6429,-83.3546,'Driving range: 2 hours',100,4,12,'All programs','All programs',null,'Jahrony','M',null,'North Oakland Visiting Vet 4416 W Walton Blvd, Waterford Twp, MI 48329','Oakland vet referal service 1400 S Telegraph Rd, Bloomfield Twp, MI 48302','Sarah Gurski - Mother 989-737-8015 preston48623@yahoo.com','2024-10-18','Bailey’s journey into dog training began in 2015 with her two family pets, an Australian cattle dog and a German shepherd. Intrigued by the art of dog training, Bailey began training in Obedience and Agility, developing a deep appreciation for the complexity and beauty of the bond it creates with handler and dog. In 2019, she and her canine companion, Bella, represented Team USA in agility at the European Open Junior in Switzerland. This experience fueled Bailey''s determination to achieve deeper connections between families and their pets, leading her to share her expertise in training. Presently, with a trio of border collies, Bailey competes in a range of activities including Agility, Obedience, Dock Diving, Disc Dog, and Fast Cat. Her border collie Rumor achieved the title of #1 Border Collie in Bad Dog Agility from 2021 to 2023, and securing a 1st Place at Agility Nationals in 2023. Bailey holds certifications in Pet CPR & First Aid, and is a Certified Stunt Dog Judge, AKC Canine Good Citizen Evaluator, AKC Temperament Testing Evaluator, Canine Conditioning and Fitness Coach, and Trick Dog Instructor. Bailey''s ultimate passion lies in helping owners create deep connections and understanding with their beloved pets.',true,'{}'::text[]) on conflict (id) do nothing;
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('7158c7ad-1b5b-554f-9095-efd1e1538cdc','Nicole Murray','nicolemurrayk9@gmail.com','nmurray.dogwise@gmail.com','nmurray@dogwiseacademy.com','(317) 695-2360','3823 Graceland Ave, Indianapolis, IN 46208','Indianapolis','IN','46208',39.8299,-86.1794,'Driving range: 3 hours',150,6,18,'All programs','All programs',null,'Jahrony','M',null,'Broadripple Animal Clinic (317) 257-5334 6225 Broadway St, Indianapolis, IN 46220','IndyVet Emergency & Specialty Hospital (317) 782-4484 5425 Victory Dr, Indianapolis, IN 46203','Andrew Ryan Murray Husband 3175388409',null,'Dogs are my passion, and I’ve dedicated my life to helping them and their owners live in harmony. I grew up in Summerville, South Carolina, and moved to Indianapolis in 2010, where I''ve been living ever since. I began my journey with dogs right after high school as a kennel technician, gaining experience in various roles including doggy daycare attendant, receptionist, and assistant manager of a kennel. My love for dogs led me to pursue certification as a dog obedience trainer from Penn Foster. Volunteering at Indy Humane and witnessing the number of dogs in shelters inspired me to become a trainer. My goal is to help prevent as many dogs as possible from ending up in shelters by strengthening the bond between dogs and their families through proper training.
