insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('885e21c9-55e7-5354-a9cb-0fea1e014510','Joseph Serrano','joseph.serrano1@yahoo.com',null,'jserrano@dogwiseacademy.com','(904) 556-0570','32914 CA-190, Springville CA 93265','Los Banos','CA','93635',37.0627,-120.8544,'Driving range: 2-3 hours',100,4,12,'All Programs','All Programs',null,'Jahrony','M',null,'Archvet animal hospital  (669) 230-5034 824 N Winchester Blvd  San Jose, CA 95128','Archvet animal hospital  (669) 230-5034 824 N Winchester Blvd  San Jose, CA 95128','Ashlee (wife)  559-513-2232','2024-03-16','As a United States Army combat veteran, my passion for training dogs is rooted in real-world experience and a deep understanding of the powerful bond between humans and canines. Over the years, I have had the privilege of working with a wide range of dogs, from high-performance working K9s to beloved family pets.
insert into trainers (id,name,email,work_email,dogwise_email,phone,address,city,state,zip,lat,lon,range_text,range_miles,capacity,monthly_capacity,programs,offering,notes,poc,shirt_size,second_location,local_vet,emergency_vet,emergency_contact,birthday,bio,active,data_flags) values ('8c723b23-8121-51ac-bc1d-3053528b918c','Olivia Sheehan','onikki96@me.com',null,'osheehan@dogwiseacademy.com','(209) 608-3468','1516 Parkside Ct, Tracy, CA 95376','Tracy','CA','95376',37.7383,-121.4345,'Driving range: 1.5 hours',75,3,9,'All programs (Can''t offer separation anxiety & aggression programs at the same time)','All Programs * 1 rehab a time','NOT taking Puppy programs OR aggression rehabs while pregnant (due in July 2025)','Jahrony','XL',null,'Jules Veterinary Center 2098337387 1755 w 11th st Tracy ca 95376','Standiford Veterinary Center 1520 Standiford Ave Modesto CA 95350','Tiffany Rodrigues (Mother)  510-861-0729','2024-03-10','Hi there I’m Olivia! I’ve been training dogs since I was about 18 years old. I fell in love with it when I rescued my first dog who was a Dutch shepherd. Watching him transform from being uncontrollable to being able to go on public outings was the greatest thing. I love being able to help clients problem solve and relationship build with their dogs and watching each dog progress to the best versions of themselves! I was a K9 Handler for the private sector for about 5 years and training on the side before I missed training more and came back full time. On my off time I enjoy traveling to new places and taking my dogs on hikes or to swim!',true,'{}'::text[]) on conflict (id) do nothing;
